/* Grid: tablet and mobile overrides (breakpoints = sizing.breakpoint-*) */
@media (max-width: 1279px) {
  :root {
    --grid-columns: 12;
    --grid-gutter: 16px;
    --grid-margin: 24px;
  }
}
@media (max-width: 767px) {
  :root {
    --grid-columns: 4;
    --grid-gutter: 16px;
    --grid-margin: 16px;
  }
}

/* Reduced motion: durations collapse to 0ms, use opacity-only transitions (see docs/FOUNDATIONS.md) */
@media (prefers-reduced-motion: reduce) {
  :root {
    --motion-duration-fast: 0ms;
    --motion-duration-base: 0ms;
    --motion-duration-slow: 0ms;
    --motion-duration-stack-offset: 0ms;
  }
}

